with supplier_summary as (select supplier_id, min(stock_qty) as min_stock_qty, sum(case when category = 'Grocery' then stock_qty else 0 end) as grocery_stock_qty from products where upper(trim(product_name)) = 'COFFEE MAKER' group by supplier_id) select s.id, s.rating, s.country, ss.min_stock_qty, ss.grocery_stock_qty from suppliers s left outer join supplier_summary ss on s.id = ss.supplier_id order by s.rating desc;
